typedef unsigned int nlUint32;
typedef int nlInt32;
typedef unsigned int nslSoundId;
typedef unsigned int nslSourceId;
typedef unsigned int nslEmitterId;

enum nslSourceTypeEnum { NSL_SOURCETYPE_SFX };

struct nslSource
{
  bool used;
  bool looping;
  char fileName[64];
  int bank;
  nslSourceId myId;
  float length;
  float paddedLength;
  nslSourceTypeEnum type;
  nlUint32 gasSourceId;
  float rawVolume;
  float pitch;
  float minDist;
  float maxDist;
};

struct nslSound
{
  bool isReady;
  bool used;
  bool inRange;
  bool isReallyReady;
  bool isPlaying;
  bool isReallyPlaying;
  bool looping;
  bool isQueuing;
  short left;
  short right;
  short old_left;
  short old_right;
  nlUint32 gasInstanceId;
  nlInt32 pauseCount;
  nlInt32 dampenCount;
  nslSourceId myId;
  nslSourceId mySource;
  nslEmitterId myEmitter;
  float rawVolume;
  float positionalVolume;
  float angle;
  float pitch;
  float minDist;
  float maxDist;
};

struct nslSystem
{
  char listenerPo[0x40];
  nslSource sourceSlots[512];
  nslSound soundSlots[256];
  char emitterSlotsAndSourceCount[0x4004];
  nlUint32 soundSlotsUsedCount;
  nlUint32 emitterSlotsUsedCount;
  nlInt32 firstInit;
  nlInt32 initialized;
  char throughClock[44];
  bool on;
};

extern nslSystem nsl;
extern void _nslInitialized();
extern void _nslCheckSourceIdValidity(nslSourceId);
extern void _nslClearSoundSlot(nlUint32, bool);
extern nlUint32 nslPs2GasRpc(int, const char *, int, int, int, int);

#define NSL_INVALID_ID 0
#define NSL_NUM_SOUNDS 256
#define NSL_ID_INCREMENT 0x400
#define NSL_SOURCE_SLOT_MASK 0xffff
#define NSL_GET_SOURCE_SLOT_FROM_ID(x) ((x) & NSL_SOURCE_SLOT_MASK)
#define NSL_SMALL3D_SOUND_SIZE .5f
#define NSL_GLOBAL_EMITTER_ID 0xffffffff
#define GAS_INVALID_ID -1
#define GAS_INSTANCE_STEREO_FLAG_BIT 0x01000000
#define GAS_RPC_ADD_INSTANCE 2
#define GAS_RPC_INSTANCE_PITCH 12
#define GAS_COMMAND_PITCH_ONE 1000
#define ASSERT_NSL_INITIALIZED() _nslInitialized()
#define ASSERT_SOURCE_ID_VALID(x) _nslCheckSourceIdValidity(x)

static nslSoundId _nslAddSound( nslSourceId soundSource, int streamOffset=0, int streamSamples=0 )
{
  if (!nsl.on) return NSL_INVALID_ID;
  ASSERT_NSL_INITIALIZED();
  ASSERT_SOURCE_ID_VALID(soundSource);

  for (int i=0; i < NSL_NUM_SOUNDS; i++) 
  {
    if (!nsl.soundSlots[i].used) 
    {
      _nslClearSoundSlot(i, false);
      nslSource *src;
      nslSound *snd;
      snd = &nsl.soundSlots[i];
      src = &nsl.sourceSlots[NSL_GET_SOURCE_SLOT_FROM_ID(soundSource)];

      snd->myId += NSL_ID_INCREMENT;
      snd->inRange = true;
      if (src->length >= NSL_SMALL3D_SOUND_SIZE)
      {
        snd->gasInstanceId = nslPs2GasRpc(GAS_RPC_ADD_INSTANCE, "", nsl.sourceSlots[NSL_GET_SOURCE_SLOT_FROM_ID(soundSource)].gasSourceId, 0, streamOffset, streamSamples);
        if (snd->gasInstanceId == (nlUint32)GAS_INVALID_ID) 
        {
          snd->inRange = false;
          return (nslSoundId)NSL_INVALID_ID;
        }
        snd->gasInstanceId =  ~GAS_INSTANCE_STEREO_FLAG_BIT & nsl.soundSlots[i].gasInstanceId;
      }
      else
      {
        snd->inRange = false;
        snd->gasInstanceId = (nlUint32)GAS_INVALID_ID;
      }

      snd->myEmitter = NSL_GLOBAL_EMITTER_ID;
      snd->mySource = soundSource;
      snd->used = true;     
      nsl.soundSlotsUsedCount++;
      snd->angle = 0;
      snd->minDist = src->minDist;
      snd->maxDist = src->maxDist;
      snd->positionalVolume = 1.0f;
      snd->rawVolume = 1.0f;
      snd->pitch = src->pitch;
      snd->old_left = 0;
      snd->old_right = 0;
      snd->pauseCount = 0;
      snd->dampenCount = 0;
      snd->isPlaying = false;
      snd->isReallyPlaying = false;
      snd->isReady = false;
      snd->isQueuing = true;
      snd->looping = src->looping;
      if ((snd->pitch != 1.0f) && (snd->gasInstanceId != (nlUint32)GAS_INVALID_ID))
      {
        nslPs2GasRpc(GAS_RPC_INSTANCE_PITCH, "", 
          snd->gasInstanceId,
          (unsigned char)(snd->pitch*GAS_COMMAND_PITCH_ONE),
          0, 0);
      }
      return snd->myId;
    }
  }
  return NSL_INVALID_ID;
}
